const catalogs: Readonly<Record<NextMuxDesktopLocale, Catalog>> = { 'zh-CN': zhCN, 'zh-TW': zhTW, en, ja, ko, es, fr, de, 'pt-BR': ptBR, ru, ar, hi };

function uncheckedComicStudioText(locale: NextMuxDesktopLocale, key: ComicStudioTextKey, values: Readonly<Record<string, string | number>> = {}): string {
    const template = (catalogs[locale] || en)[key] || en[key];
    return template.replace(/\{(\w+)\}/g, (match, name: string) => name in values ? String(values[name]) : match);
}

/** Example voice commands shown in the editor; they are also valid input for the local parser. */
export function comicVoiceExamples(locale: NextMuxDesktopLocale): readonly string[] {
    if (locale === 'zh-TW') return ['快進到 30 秒', '後退一秒', '停留在 12 秒', '前進到第 2 集', '背景再深一點'];
    if (locale === 'zh-CN') return ['快进到 30 秒', '后退一秒', '停留在 12 秒', '前进到第 2 集', '背景再深一点'];
    return ['go to 30 seconds', 'rewind 1 second', 'pause', 'play episode 2', 'make the background darker'];
}

