export const COMIC_SHOT_FIELD_TEXT: Readonly<Record<NextMuxDesktopLocale, Readonly<Record<ComicShotFieldTextKey, string>>>> = Object.fromEntries(
    Object.entries(shotFieldRows).map(([locale, row]) => [locale, { ...Object.fromEntries(row.split('|').map((value, index) => [shotFieldKeys[index], value])), motionVisionRequired: motionVisionRequired[locale as NextMuxDesktopLocale] }])
) as Record<NextMuxDesktopLocale, Record<ComicShotFieldTextKey, string>>;
function uncheckedComicShotFieldText(locale: NextMuxDesktopLocale, key: ComicShotFieldTextKey): string {
    return (COMIC_SHOT_FIELD_TEXT[locale] || COMIC_SHOT_FIELD_TEXT.en)[key];
}

/** Text lookups that never throw: an unknown key or language falls back (see nextmux-copy-fallback.ts). */
export function comicStudioText(locale: Parameters<typeof uncheckedComicStudioText>[0], key: Parameters<typeof uncheckedComicStudioText>[1], ...rest: AfterLocaleAndKey<Parameters<typeof uncheckedComicStudioText>>): string {
    return totalCopy(locale, key, language => uncheckedComicStudioText(language, key, ...rest));
}
export function comicShotFieldText(locale: Parameters<typeof uncheckedComicShotFieldText>[0], key: Parameters<typeof uncheckedComicShotFieldText>[1], ...rest: AfterLocaleAndKey<Parameters<typeof uncheckedComicShotFieldText>>): string {
    return totalCopy(locale, key, language => uncheckedComicShotFieldText(language, key, ...rest));
}
